package com.aistock.market.marketlifecycle;
import com.aistock.common.*;import com.aistock.common.marketlifecycle.MarketLifecycleContract;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/market-version-use-proofs") public final class MarketLocalUseProofController {
 private final MarketComparisonUseOwner uses;private final com.aistock.market.alert.AlertLocalUseOwner alerts;public MarketLocalUseProofController(MarketComparisonUseOwner uses){this(uses,null);}
 @org.springframework.beans.factory.annotation.Autowired public MarketLocalUseProofController(MarketComparisonUseOwner uses,com.aistock.market.alert.AlertLocalUseOwner alerts){this.uses=uses;this.alerts=alerts;}
 @GetMapping("/capabilities")public ApiResponse<?> capabilities(HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw MarketLifecycleContract.invalid();var enabled=new ArrayList<String>();if(uses.enabled())enabled.add("COMPARISON_EVIDENCE_PUBLISH");if(alerts!=null&&alerts.enabled())enabled.add("ALERT_EVIDENCE_PUBLISH");return ApiResponse.success(Map.of("protocolVersion",MarketLifecycleContract.PROTOCOL,"supportedPurposes",List.of("COMPARISON_EVIDENCE_PUBLISH","ALERT_EVIDENCE_PUBLISH"),"enabledPurposes",enabled,"consumerIntegration","PARTIAL","actionsEnabled",false),TraceIds.normalize(r.getHeader("X-Trace-Id")));}
 @GetMapping("/{purpose}/{operation}")public ApiResponse<?> proof(@PathVariable String purpose,@PathVariable UUID operation,@RequestParam MultiValueMap<String,String> query,HttpServletRequest r){if(!Set.of("COMPARISON_EVIDENCE_PUBLISH","ALERT_EVIDENCE_PUBLISH").contains(purpose)||!query.keySet().equals(Set.of("generation"))||query.get("generation").size()!=1)throw MarketLifecycleContract.invalid();var value="COMPARISON_EVIDENCE_PUBLISH".equals(purpose)?uses.proof(operation,query.getFirst("generation")):alerts==null?null:alerts.proof(operation,query.getFirst("generation"));if(value==null)throw MarketComparisonUseOwner.unavailable();return ApiResponse.success(value,TraceIds.normalize(r.getHeader("X-Trace-Id")));}
}
